  `state` smallint unsigned NOT NULL,
  `statedone` smallint unsigned NOT NULL,
  `channel` smallint unsigned NOT NULL,
  `casterimpact` smallint unsigned NOT NULL,
  `targetimpact` smallint unsigned NOT NULL,
  `castertargeting` smallint unsigned NOT NULL,
  `missiletargeting` smallint unsigned NOT NULL,
  `instantarea` smallint unsigned NOT NULL,
  `persistentarea` smallint unsigned NOT NULL,
  `casterstate` smallint unsigned NOT NULL,
  `targetstate` smallint unsigned NOT NULL,
  `missile` smallint unsigned NOT NULL,
  `impactarea` smallint unsigned NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `aowow_spelldifficulty` (
  `normal10` mediumint unsigned NOT NULL,
  `normal25` mediumint unsigned NOT NULL,
  `heroic10` mediumint unsigned NOT NULL,
  `heroic25` mediumint unsigned NOT NULL,
  `mapType` tinyint unsigned NOT NULL,
  KEY `normal10` (`normal10`),
  KEY `normal25` (`normal25`),
  KEY `heroic10` (`heroic10`),
  KEY `heroic25` (`heroic25`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `aowow_sql_update_journal` (
  `date` int unsigned NOT NULL,
  `part` tinyint unsigned NOT NULL,
  `checksum` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` varchar(16) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `statements` int unsigned NOT NULL DEFAULT '0',
  PRIMARY KEY (`date`,`part`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `aowow_talents` (
  `id` smallint unsigned NOT NULL,
  `class` tinyint unsigned NOT NULL,
  `petTypeMask` tinyint unsigned NOT NULL,
  `tab` tinyint unsigned NOT NULL,
  `row` tinyint unsigned NOT NULL,
  `col` tinyint unsigned NOT NULL,
  `spell` mediumint unsigned NOT NULL,
  `rank` tinyint unsigned NOT NULL,
  PRIMARY KEY (`id`,`rank`),
  KEY `spell` (`spell`),
  KEY `class` (`class`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `aowow_taxinodes` (
  `id` smallint unsigned NOT NULL,
  `mapId` smallint unsigned NOT NULL,
  `mapX` float unsigned NOT NULL,
  `mapY` float unsigned NOT NULL,
  `areaId` smallint unsigned NOT NULL,
  `areaX` float unsigned NOT NULL,
  `areaY` float unsigned NOT NULL,
  `type` tinyint unsigned NOT NULL,
  `typeId` mediumint unsigned NOT NULL,
  `reactA` tinyint NOT NULL,
  `reactH` tinyint NOT NULL,
  `name_loc0` varchar(46) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_loc2` varchar(62) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_loc3` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_loc4` varchar(55) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_loc6` varchar(63) COLLATE utf8mb4_unicode_ci NOT NULL,
  `name_loc8` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

